-- SAMPLE content for the Study Abroad pages of 5 countries (UK, USA, Canada, Australia, Germany).
-- Text is general and illustrative: review and edit in Directus before relying on it.
-- Fills the text blocks on countries and the list rows in country_sections (replaces earlier placeholder rows).
-- Safe to re-run: it replaces the '[Sample]' rows it created.

BEGIN;
DELETE FROM country_sections WHERE title LIKE '[Placeholder]%' OR (title LIKE '[Sample]%' AND country_id IN (SELECT id FROM countries WHERE slug IN ('united-kingdom', 'united-states', 'canada', 'australia', 'germany')));
UPDATE countries SET why_title = 'Why study in the UK?', why_body = '<p>The UK is home to some of the world''s oldest and most respected universities, with a strong global reputation for teaching and research.</p><ul><li>Many taught Master''s degrees can be completed in one year</li><li>Strong links with industry and a wide choice of subjects</li><li>Post-study work options through the Graduate Route</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>International students usually need a <strong>Student visa</strong>. You need a confirmed place (a CAS from your university), proof of funds and English language ability.</p><ul><li>Apply online before you travel</li><li>Provide passport, CAS, financial evidence and, where required, a TB test</li><li>Check the official UK government site for current rules and fees</li></ul>', application_title = 'Application requirements', application_body = '<p>Undergraduate applications generally go through UCAS; postgraduate applications are usually made directly to the university.</p><ul><li>Academic transcripts and certificates</li><li>Personal statement and references</li><li>Proof of English proficiency</li><li>Passport copy</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Costs vary by university, course and city. Tuition for international students is generally higher than for home students, and living costs are higher in London than elsewhere.</p><ul><li>Tuition: varies widely by course</li><li>Accommodation and food: major monthly expense</li><li>Health surcharge and visa fee</li></ul>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Entry requirements depend on the level of study.</p><ul><li>Bachelor''s: completed secondary education with strong grades</li><li>Master''s: a relevant bachelor''s degree</li><li>English test score such as IELTS where required</li></ul>' WHERE slug = 'united-kingdom';
UPDATE countries SET why_title = 'Why study in the USA?', why_body = '<p>The USA offers a huge range of universities and flexible degree programmes, with world-leading research and a strong campus culture.</p><ul><li>Flexibility to choose and change majors</li><li>Research and internship opportunities</li><li>Optional Practical Training (OPT) after graduation</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Most international students need an <strong>F-1 student visa</strong>. After admission, your university issues a Form I-20, which you use to apply and attend a visa interview.</p><ul><li>Pay the SEVIS fee</li><li>Complete the visa application and interview</li><li>Show proof of funds and intent to study</li></ul>', application_title = 'Application requirements', application_body = '<p>Most universities use their own portal or the Common App for undergraduate admission.</p><ul><li>Transcripts and test scores</li><li>Statement of purpose or essays</li><li>Letters of recommendation</li><li>Proof of English proficiency</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Costs differ greatly between public and private universities and by state. Plan for tuition, housing, health insurance and books.</p><ul><li>Tuition: private universities usually cost more</li><li>Housing and meals</li><li>Health insurance is often mandatory</li></ul>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements vary by university and programme.</p><ul><li>Undergraduate: high school completion, SAT/ACT optional at many universities</li><li>Graduate: bachelor''s degree, GRE/GMAT for some programmes</li><li>TOEFL or IELTS for English proficiency</li></ul>' WHERE slug = 'united-states';
UPDATE countries SET why_title = 'Why study in Canada?', why_body = '<p>Canada is known for high-quality education, welcoming cities and a safe, multicultural environment.</p><ul><li>Globally recognised degrees</li><li>Work during studies and Post-Graduation Work Permit options</li><li>Strong pathways for skilled graduates</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>You usually need a <strong>study permit</strong> in addition to an acceptance letter from a designated learning institution.</p><ul><li>Letter of acceptance</li><li>Proof of funds</li><li>Passport and photos, plus medical exam or police certificate where required</li></ul>', application_title = 'Application requirements', application_body = '<p>Apply directly to each university or college, or through a provincial application centre where applicable.</p><ul><li>Academic records</li><li>English or French proficiency</li><li>Statement of purpose and references (for many programmes)</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition is often lower than in the USA or UK, but varies by province and programme.</p><ul><li>Tuition</li><li>Living costs depend on the city</li><li>Health insurance, depending on the province</li></ul>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Eligibility depends on the programme and institution.</p><ul><li>Bachelor''s: secondary school completion</li><li>Master''s: relevant bachelor''s degree</li><li>Language test scores such as IELTS</li></ul>' WHERE slug = 'canada';
UPDATE countries SET why_title = 'Why study in Australia?', why_body = '<p>Australia combines highly ranked universities with an outdoor lifestyle and a supportive international student community.</p><ul><li>Strong in engineering, health and business</li><li>Work rights during study</li><li>Post-study work visa options</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>International students need a <strong>Student visa (subclass 500)</strong>. You need a Confirmation of Enrolment (CoE) from your institution.</p><ul><li>Genuine Student requirement</li><li>Proof of funds and health cover (OSHC)</li><li>English proficiency evidence</li></ul>', application_title = 'Application requirements', application_body = '<p>Apply directly to the university or through an education agent.</p><ul><li>Academic transcripts</li><li>English test results</li><li>Passport copy and statement of purpose</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition and living costs are significant, with large differences between cities.</p><ul><li>Tuition by course and university</li><li>Overseas Student Health Cover</li><li>Accommodation and daily expenses</li></ul>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the course level.</p><ul><li>Bachelor''s: completed secondary education</li><li>Master''s: relevant bachelor''s degree</li><li>English requirement, e.g. IELTS</li></ul>' WHERE slug = 'australia';
UPDATE countries SET why_title = 'Why study in Germany?', why_body = '<p>Germany is known for engineering excellence, research and low or no tuition at many public universities.</p><ul><li>Many public universities charge little or no tuition</li><li>Strong industry connections</li><li>Options to stay and look for work after graduation</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Non-EU students typically apply for a <strong>student visa</strong> and then a residence permit after arrival.</p><ul><li>Admission letter</li><li>Proof of financial resources (blocked account)</li><li>Health insurance</li></ul>', application_title = 'Application requirements', application_body = '<p>Applications go directly to the university or through uni-assist for many programmes.</p><ul><li>Certified academic documents</li><li>Language certificate (German or English)</li><li>CV and motivation letter</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition at public universities is low, but you must plan for living costs and a blocked account.</p><ul><li>Semester contribution fee</li><li>Accommodation and food</li><li>Health insurance</li></ul>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on your previous education and programme.</p><ul><li>University entrance qualification recognised in Germany</li><li>German or English proficiency</li><li>Some programmes require entrance exams</li></ul>' WHERE slug = 'germany';
COMMIT;
